"""Gera candidatos de emoji (código + nome em inglês + grupo) a partir da lista extraída da fonte do Windows.
Os nomes vêm do unicodedata (Unicode 15.1). Saída: emoji_candidates.json"""
import json, re, sys, unicodedata

d = json.load(open(sys.argv[1]))
OUT = sys.argv[2]

ZWJ, VS16, KEYCAP = 0x200D, 0xFE0F, 0x20E3
TONES = set(range(0x1F3FB, 0x1F400))
RI = set(range(0x1F1E6, 0x1F200))
TAGS = set(range(0xE0020, 0xE0080))
HAIR = set(range(0x1F9B0, 0x1F9B4))

def nm(cp):
    try:
        return unicodedata.name(chr(cp))
    except ValueError:
        return ''

cands = {}
def add(seq):
    seq = [c for c in seq if c != VS16]
    if not seq or any(c in TONES for c in seq):
        return
    if seq[0] == ZWJ or seq[-1] == ZWJ:
        return
    if len(seq) == 1 and (seq[0] in TONES or seq[0] in RI or seq[0] in TAGS or seq[0] in HAIR or seq[0] < 0xA9):
        return
    key = tuple(seq)
    cands.setdefault(key, None)

for cp in d['singles']:
    if cp >= 0xA9:
        add([cp])
for s in d['seqs']:
    add(s)
for k in '0123456789#*':
    add([ord(k), KEYCAP])

PEOPLE_RE = re.compile(r'\b(HAND|HANDS|FINGER|FIST|THUMBS|CLAPPING|WAVING|NAIL POLISH|SELFIE|BICEPS|LEG|FOOT|EAR|NOSE|BRAIN|ANATOMICAL|LUNGS|TOOTH|BONE|EYES|EYE|TONGUE|MOUTH|LIPS|BABY|CHILD|BOY|GIRL|PERSON|PEOPLE|MAN|WOMAN|MEN|WOMEN|PRINCE|PRINCESS|FAMILY|KISS|COUPLE|SANTA|CLAUS|MAGE|FAIRY|VAMPIRE|MERPERSON|MERMAID|MERMAN|ELF|GENIE|ZOMBIE|TROLL|SUPERHERO|SUPERVILLAIN|NINJA|CONSTRUCTION WORKER|GUARDSMAN|POLICE OFFICER|SLEUTH|DETECTIVE|OLDER|ADULT|BRIDE|ANGEL|DANCER|SPEAKING HEAD|BUST|BUSTS|FOOTPRINTS|PALM|PALMS|PREGNANT|BREAST|HUGGING|MOTHER|FATHER|CROWN WITH|WEARING TURBAN|GUA PI MAO|HEADSCARF|TUXEDO|VEIL|FACE MASSAGE|HAIRCUT|SURFER|SWIMMER|ROWBOAT|BATH|SLEEPING ACCOMMODATION|WRESTLERS|JUGGLING|CARTWHEEL|HANDBALL|WATER POLO|GOLFER|HORSE RACING|SNOWBOARDER|SKIER|LIFTING WEIGHTS|BICYCLIST|MOUNTAIN BICYCLIST|LOTUS POSITION|STANDING|KNEELING|RUNNER|PEDESTRIAN|CLIMBING|STEAMY ROOM|FENCER|BOWING|RAISING|FROWNING|POUTING|TIPPING|NO GOOD|OK GESTURE|SHRUG|FACEPALM|DEAF|WHITE CANE|WHEELCHAIR|ARM|BEARD|BALD|SKIN TONE|EMOJI COMPONENT)\b')
ANIMAL_RE = re.compile(r'\b(MONKEY|GORILLA|ORANGUTAN|DOG|POODLE|WOLF|FOX|RACCOON|CAT|LION|TIGER|LEOPARD|HORSE|MOOSE|DONKEY|UNICORN|ZEBRA|DEER|BISON|COW|OX|BUFFALO|PIG|BOAR|RAM|SHEEP|EWE|GOAT|CAMEL|LLAMA|GIRAFFE|ELEPHANT|MAMMOTH|RHINOCEROS|HIPPOPOTAMUS|MOUSE|RAT|HAMSTER|RABBIT|CHIPMUNK|BEAVER|HEDGEHOG|BAT|BEAR|KOALA|PANDA|SLOTH|OTTER|SKUNK|KANGAROO|BADGER|PAW|TURKEY|CHICKEN|ROOSTER|CHICK|BIRD|PENGUIN|DOVE|EAGLE|DUCK|SWAN|OWL|DODO|FEATHER|FLAMINGO|PEACOCK|PARROT|GOOSE|WING|FROG|CROCODILE|TURTLE|LIZARD|SNAKE|DRAGON|SAUROPOD|T-REX|WHALE|DOLPHIN|SEAL|FISH|BLOWFISH|SHARK|OCTOPUS|SHELL|CORAL|JELLYFISH|SNAIL|BUTTERFLY|BUG|ANT|HONEYBEE|BEETLE|LADY BEETLE|CRICKET|COCKROACH|SPIDER|SCORPION|MOSQUITO|FLY|WORM|MICROBE|BOUQUET|CHERRY BLOSSOM|WHITE FLOWER|LOTUS|ROSETTE|ROSE|WILTED|HIBISCUS|SUNFLOWER|BLOSSOM|TULIP|HYACINTH|SEEDLING|POTTED PLANT|EVERGREEN|DECIDUOUS|PALM TREE|CACTUS|SHEAF OF RICE|HERB|SHAMROCK|FOUR LEAF CLOVER|MAPLE LEAF|FALLEN LEAF|LEAF FLUTTERING|EMPTY NEST|NEST WITH EGGS|MUSHROOM|ROCK|WOOD|CRAB|LOBSTER|SHRIMP|SQUID|OYSTER|FLOWER|PLANT|TREE|LEAVES|CLOVER|HYENA|JACKAL|MOOSE|GOOSE)\b')
FOOD_RE = re.compile(r'\b(GRAPES|MELON|WATERMELON|TANGERINE|LEMON|LIME|BANANA|PINEAPPLE|MANGO|APPLE|PEAR|PEACH|CHERRIES|STRAWBERRY|BLUEBERRIES|KIWIFRUIT|TOMATO|OLIVE|COCONUT|AVOCADO|AUBERGINE|EGGPLANT|POTATO|CARROT|EAR OF MAIZE|CORN|HOT PEPPER|BELL PEPPER|CUCUMBER|LEAFY GREEN|BROCCOLI|GARLIC|ONION|PEANUTS|BEANS|CHESTNUT|GINGER|PEA POD|BREAD|CROISSANT|BAGUETTE|FLATBREAD|PRETZEL|BAGEL|PANCAKES|WAFFLE|CHEESE|MEAT|POULTRY|CUT OF MEAT|BACON|HAMBURGER|FRENCH FRIES|PIZZA|HOT DOG|SANDWICH|TACO|BURRITO|TAMALE|STUFFED FLATBREAD|FALAFEL|EGG|COOKING|SHALLOW PAN|POT OF FOOD|FONDUE|BOWL WITH SPOON|GREEN SALAD|POPCORN|BUTTER|SALT|CANNED FOOD|BENTO|RICE|CURRY|SPAGHETTI|ROASTED SWEET POTATO|ODEN|SUSHI|FRIED SHRIMP|FISH CAKE|MOON CAKE|DANGO|DUMPLING|FORTUNE COOKIE|TAKEOUT BOX|SOFT ICE CREAM|SHAVED ICE|ICE CREAM|DOUGHNUT|COOKIE|BIRTHDAY CAKE|SHORTCAKE|CUPCAKE|PIE|CHOCOLATE|CANDY|LOLLIPOP|CUSTARD|HONEY POT|BABY BOTTLE|GLASS OF MILK|HOT BEVERAGE|TEAPOT|TEACUP|SAKE|BOTTLE WITH POPPING CORK|WINE|COCKTAIL|TROPICAL DRINK|BEER|CLINKING|TUMBLER|POURING LIQUID|CUP WITH STRAW|BUBBLE TEA|BEVERAGE BOX|MATE|ICE CUBE|CHOPSTICKS|FORK|KNIFE|SPOON|AMPHORA|JAR|STEW|SPAGHETTI|FOOD|MEAL|DRINK|BURGER|GOOSE)\b')
TRAVEL_RE = re.compile(r'\b(GLOBE|WORLD MAP|MAP OF JAPAN|COMPASS|MOUNTAIN|VOLCANO|CAMPING|BEACH|DESERT|ISLAND|NATIONAL PARK|STADIUM|CLASSICAL BUILDING|BUILDING|BRICK|HUT|HOUSE|HOUSES|OFFICE|POST OFFICE|HOSPITAL|BANK|HOTEL|LOVE HOTEL|CONVENIENCE STORE|SCHOOL|DEPARTMENT STORE|FACTORY|CASTLE|WEDDING|TOKYO TOWER|STATUE OF LIBERTY|CHURCH|MOSQUE|HINDU TEMPLE|SYNAGOGUE|SHINTO|KAABA|FOUNTAIN|TENT|FOGGY|NIGHT WITH STARS|CITYSCAPE|SUNRISE|SUNSET|BRIDGE AT NIGHT|HOT SPRINGS|CAROUSEL|PLAYGROUND|FERRIS WHEEL|ROLLER COASTER|BARBER POLE|CIRCUS TENT|LOCOMOTIVE|RAILWAY|TRAIN|METRO|LIGHT RAIL|STATION|TRAM|MONORAIL|BUS|TROLLEYBUS|MINIBUS|AMBULANCE|FIRE ENGINE|POLICE CAR|TAXI|AUTOMOBILE|CAR|PICKUP|DELIVERY TRUCK|TRUCK|TRACTOR|RACING|MOTORCYCLE|SCOOTER|WHEELCHAIR|BICYCLE|SKATEBOARD|ROLLER SKATE|BUS STOP|MOTORWAY|RAILWAY TRACK|OIL DRUM|FUEL PUMP|WHEEL|POLICE CARS|TRAFFIC LIGHT|OCTAGONAL SIGN|CONSTRUCTION SIGN|ANCHOR|RING BUOY|SAILBOAT|CANOE|SPEEDBOAT|PASSENGER SHIP|FERRY|MOTOR BOAT|SHIP|AIRPLANE|AIRPLANE DEPARTURE|AIRPLANE ARRIVING|PARACHUTE|SEAT|HELICOPTER|SUSPENSION RAILWAY|MOUNTAIN CABLEWAY|AERIAL TRAMWAY|SATELLITE|ROCKET|FLYING SAUCER|BELLHOP|LUGGAGE|HOURGLASS|WATCH|ALARM CLOCK|STOPWATCH|TIMER CLOCK|MANTELPIECE CLOCK|CLOCK FACE|NEW MOON|MOON|FIRST QUARTER|FULL MOON|LAST QUARTER|CRESCENT|THERMOMETER|SUN|RINGED PLANET|STAR|GLOWING STAR|SHOOTING STAR|MILKY WAY|CLOUD|THUNDER|TORNADO|FOG|WIND|CYCLONE|RAINBOW|UMBRELLA|HIGH VOLTAGE|SNOWFLAKE|SNOWMAN|COMET|FIRE|DROPLET|WATER WAVE|ROAD|HOLE|DUSK|SNOW CAPPED|PLANE|FLIGHT|BOAT|STATION|VEHICLE|BRIDGE|TEMPLE|PAGODA|RAIN|LIGHTNING|TSUNAMI)\b')
ACTIVITY_RE = re.compile(r'\b(JACK-O-LANTERN|CHRISTMAS TREE|FIREWORKS|FIREWORK SPARKLER|FIRECRACKER|SPARKLES|BALLOON|PARTY POPPER|CONFETTI BALL|TANABATA|PINE DECORATION|JAPANESE DOLLS|CARP STREAMER|WIND CHIME|MOON VIEWING|RED GIFT ENVELOPE|RIBBON|WRAPPED PRESENT|REMINDER RIBBON|ADMISSION TICKETS|TICKET|MILITARY MEDAL|TROPHY|SPORTS MEDAL|MEDAL|SOCCER|BASEBALL|SOFTBALL|BASKETBALL|VOLLEYBALL|AMERICAN FOOTBALL|RUGBY|TENNIS|FLYING DISC|BOWLING|CRICKET BAT|FIELD HOCKEY|ICE HOCKEY|LACROSSE|TABLE TENNIS|BADMINTON|BOXING GLOVE|MARTIAL ARTS|GOAL NET|FLAG IN HOLE|ICE SKATE|FISHING POLE|DIVING MASK|RUNNING SHIRT|SKI|SLED|CURLING STONE|DIRECT HIT|YO-YO|KITE|PISTOL|WATER PISTOL|BILLIARDS|CRYSTAL BALL|MAGIC WAND|NAZAR AMULET|HAMSA|VIDEO GAME|JOYSTICK|SLOT MACHINE|GAME DIE|PUZZLE PIECE|TEDDY BEAR|PINATA|MIRROR BALL|NESTING DOLLS|SPADE SUIT|HEART SUIT|DIAMOND SUIT|CLUB SUIT|CHESS PAWN|JOKER|MAHJONG|FLOWER PLAYING CARDS|PERFORMING ARTS|FRAME WITH PICTURE|ARTIST PALETTE|THREAD|SEWING NEEDLE|YARN|KNOT|BALL|GAME|SPORT|PLAYING CARD|DICE)\b')
OBJECT_RE = re.compile(r'\b(GLASSES|SUNGLASSES|GOGGLES|LAB COAT|SAFETY VEST|NECKTIE|SHIRT|JEANS|SCARF|GLOVES|COAT|SOCKS|DRESS|KIMONO|SARI|ONE-PIECE|BRIEFS|SHORTS|BIKINI|CLOTHES|FOLDING HAND FAN|PURSE|HANDBAG|POUCH|SHOPPING BAGS|SCHOOL SATCHEL|THONG SANDAL|SHOE|HIKING BOOT|HEELED|SANDAL|BALLET SHOES|BOOT|HAIR PICK|CROWN|HAT|TOP HAT|GRADUATION CAP|BILLED CAP|HELMET|PRAYER BEADS|LIPSTICK|RING|GEM STONE|SPEAKER|LOUDSPEAKER|MEGAPHONE|POSTAL HORN|BELL|MUSICAL|MICROPHONE|LEVEL SLIDER|CONTROL KNOBS|HEADPHONE|RADIO|SAXOPHONE|ACCORDION|GUITAR|KEYBOARD|TRUMPET|VIOLIN|BANJO|DRUM|LONG DRUM|MARACAS|FLUTE|MOBILE PHONE|TELEPHONE|PAGER|FAX|BATTERY|PLUG|LAPTOP|DESKTOP COMPUTER|PRINTER|COMPUTER|TRACKBALL|MINIDISC|FLOPPY|OPTICAL DISC|DVD|ABACUS|MOVIE CAMERA|FILM|PROJECTOR|CLAPPER|TELEVISION|CAMERA|VIDEO CAMERA|VIDEOCASSETTE|MAGNIFYING|CANDLE|LIGHT BULB|FLASHLIGHT|LANTERN|DIYA|NOTEBOOK|BOOK|BOOKS|LEDGER|PAGE|SCROLL|NEWSPAPER|BOOKMARK|LABEL|MONEY|COIN|YEN|DOLLAR|EURO|POUND|BANKNOTE|CREDIT CARD|RECEIPT|CHART|ENVELOPE|E-MAIL|INCOMING|OUTBOX|INBOX|PACKAGE|MAILBOX|POSTBOX|BALLOT|PENCIL|FOUNTAIN PEN|PEN|PAINTBRUSH|CRAYON|MEMO|BRIEFCASE|FILE FOLDER|FOLDER|DIVIDERS|CALENDAR|NOTEPAD|CARD INDEX|CLIPBOARD|PUSHPIN|PAPERCLIP|STRAIGHT RULER|TRIANGULAR RULER|SCISSORS|CARD FILE|FILE CABINET|WASTEBASKET|LOCK|KEY|HAMMER|AXE|PICK|DAGGER|SWORD|BOW AND ARROW|SHIELD|CARPENTRY SAW|WRENCH|SCREWDRIVER|NUT AND BOLT|GEAR|CLAMP|BALANCE SCALE|WHITE CANE|LINK|CHAINS|HOOK|TOOLBOX|MAGNET|LADDER|ALEMBIC|TEST TUBE|PETRI DISH|DNA|MICROSCOPE|TELESCOPE|ANTENNA|SYRINGE|DROP OF BLOOD|PILL|ADHESIVE BANDAGE|CRUTCH|STETHOSCOPE|X-RAY|DOOR|ELEVATOR|WINDOW|BED|COUCH|CHAIR|TOILET|PLUNGER|SHOWER|BATHTUB|MOUSE TRAP|RAZOR|LOTION|SAFETY PIN|BROOM|BASKET|ROLL OF PAPER|BUCKET|SOAP|BUBBLES|TOOTHBRUSH|SPONGE|FIRE EXTINGUISHER|SHOPPING TROLLEY|SMOKING|COFFIN|HEADSTONE|FUNERAL URN|MOYAI|PLACARD|IDENTIFICATION CARD|BOMB|PRAYER|PIN|SATELLITE ANTENNA|HAIR PICK|WING|BOOMERANG|CANDLE|BOX|PACKAGE|TAG|LEDGER|CLIP|TOOL|SPIRAL|BLUE BOOK|GREEN BOOK|ORANGE BOOK|CLOSED BOOK|OPEN BOOK)\b')

def group(seq, name):
    cp = seq[0]
    if any(c in RI or c in TAGS for c in seq) or cp in (0x1F3C1, 0x1F6A9, 0x1F38C, 0x1F3F4, 0x1F3F3):
        return 'flags'
    if KEYCAP in seq:
        return 'symbols'
    if ZWJ in seq:
        first = nm(cp)
        if re.search(r'\b(MAN|WOMAN|PERSON|ADULT|FAMILY|KISS|COUPLE|BOY|GIRL|CHILD|PEOPLE|HANDS|MERPERSON|FAIRY|ELF|GENIE|ZOMBIE|VAMPIRE|MAGE|SUPERHERO|SUPERVILLAIN|POLICE|GUARDSMAN|DETECTIVE|SLEUTH|CONSTRUCTION|WEARING|TURBAN|BEARD|BALD|SWIMMER|SURFER|ROWBOAT|BICYCLIST|GOLFER|LIFTING|BOUNCING|RUNNER|PEDESTRIAN|KNEELING|STANDING|BOWING|RAISING|FROWNING|POUTING|TIPPING|NO GOOD|OK GESTURE|SHRUG|FACEPALM|DEAF|JUGGLING|CARTWHEEL|HANDBALL|WATER POLO|WRESTLERS|CLIMBING|STEAMY|SAUNA|HAIRCUT|MASSAGE|EYE|FACE|BLACK|BUSTS|DANCER)\b', first):
            if re.search(r'\bFACE\b', first) and not re.search(r'\b(PERSON|MAN|WOMAN)\b', first):
                return 'smileys'
            if first in ('EYE',):
                return 'smileys'
            return 'people'
        if re.search(r'\b(CAT|DOG|BEAR|BIRD|GOOSE|PHOENIX|LIME|MUSHROOM|POLAR|FIRE)\b', name):
            return 'animals' if not re.search(r'\b(LIME|MUSHROOM)\b', name) else 'food'
        if 'HEART' in first:
            return 'smileys'
        if 'CHAINS' in name or 'BROKEN' in name:
            return 'objects'
        if 'RAINBOW' in name or 'TRANSGENDER' in name or 'PIRATE' in name:
            return 'flags'
        if 'SNOWFLAKE' in name or 'SNOWMAN' in name:
            return 'animals'
        return 'symbols'
    n = name
    if re.search(r'\bFACE\b', n) and not re.search(r'\b(DOG|CAT|MONKEY|TIGER|HORSE|COW|PIG|MOUSE|RABBIT|BEAR|PANDA|WOLF|FOX|LION|FROG|DRAGON|UNICORN|SPOUTING WHALE|MOON|SUN|CLOCK|CLOWN)\b', n):
        return 'smileys'
    if re.search(r'\b(CLOWN FACE)\b', n) or re.search(r'\b(SKULL|PILE OF POO|GHOST|EXTRATERRESTRIAL|ALIEN|ROBOT|OGRE|GOBLIN|KISS MARK|LOVE LETTER|SEE-NO-EVIL|HEAR-NO-EVIL|SPEAK-NO-EVIL|HEART|ANGER SYMBOL|COLLISION|DIZZY SYMBOL|SPLASHING SWEAT|DASH SYMBOL|HOLE|SPEECH BALLOON|THOUGHT BALLOON|RIGHT ANGER BUBBLE|LEFT SPEECH BUBBLE|SLEEPING SYMBOL|HUNDRED POINTS|BOMB|EYE IN SPEECH BUBBLE|SMILING CAT|GRINNING CAT|CAT FACE WITH|WEARY CAT|CRYING CAT|POUTING CAT|KISSING CAT|JAPANESE OGRE|JAPANESE GOBLIN)\b', n):
        if 'HEART SUIT' in n or 'HEART DECORATION' in n or 'HEART WITH' in n and 'ARROW' not in n and 'RIBBON' not in n and 'SPARKLE' not in n:
            pass
        if 'HEART SUIT' in n:
            return 'activities'
        if 'ANATOMICAL' in n:
            return 'people'
        return 'smileys'
    if re.search(r'\bCAT FACE\b', n):
        return 'smileys'
    if re.search(r'\b(MOON|SUN) WITH FACE\b', n) or 'NEW MOON WITH FACE' in n or 'FULL MOON WITH FACE' in n:
        return 'travel'
    if PEOPLE_RE.search(n):
        # exceções que não são pessoas
        if re.search(r'\b(HANDBAG|HAND FAN|MAN IN BUSINESS SUIT LEVITATING)\b', n):
            pass
        elif re.search(r'\b(EAR OF RICE|EAR OF MAIZE|PINEAPPLE|PEAR|BALLET|SPEAKER|BATHTUB|HOUSE|BABY BOTTLE|BABY CHICK|HATCHING|PALM TREE|STANDING|WOMANS|MANS SHOE|WOMANS HAT|WOMANS CLOTHES|WOMANS SANDAL|BRIEFCASE|HANDSHAKE)\b', n) and 'PERSON' not in n:
            if 'HANDSHAKE' in n:
                return 'people'
        else:
            return 'people'
    if ANIMAL_RE.search(n) and not re.search(r'\b(FISHING|FISH CAKE|FRIED SHRIMP|CANNED|BABY BOTTLE|EGG|KITE|FEATHER|CAT FACE|DOG FACE)\b', n) or re.search(r'\b(DOG FACE|CAT FACE|MONKEY FACE|TIGER FACE|HORSE FACE|COW FACE|PIG FACE|MOUSE FACE|RABBIT FACE|BEAR FACE|PANDA FACE|WOLF FACE|FOX FACE|LION FACE|FROG FACE|DRAGON FACE|UNICORN FACE|SPOUTING WHALE|FEATHER)\b', n):
        if re.search(r'\b(ROSE|TULIP|BLOSSOM|FLOWER|PLANT|TREE|LEAF|HERB|SHAMROCK|CLOVER|CACTUS|SEEDLING|SHEAF|MUSHROOM|NEST|ROCK|WOOD|BOUQUET|ROSETTE|LOTUS|HIBISCUS|SUNFLOWER|HYACINTH|CORAL|FEATHER|WING)\b', n) and re.search(r'\b(BRICK|ROCKET|ROCK MUSIC)\b', n):
            return 'objects'
        if re.search(r'\b(CRAB|LOBSTER|SHRIMP|SQUID|OYSTER)\b', n):
            return 'food' if 'OYSTER' in n else 'animals'
        return 'animals'
    if FOOD_RE.search(n) and not re.search(r'\b(BEANS|NEST WITH EGGS|EGG CRATE)\b', n) or 'BEANS' in n:
        return 'food'
    if re.search(r'\b(EGG)\b', n):
        return 'food'
    if ACTIVITY_RE.search(n):
        return 'activities'
    if TRAVEL_RE.search(n) and not re.search(r'\b(STAR OF DAVID|STAR AND CRESCENT|SIX POINTED|EIGHT SPOKED|EIGHT POINTED|STAR-SHAPED|DOTTED SIX|CLOCKWISE|ARROW|BLACK SUN WITH RAYS)\b', n):
        return 'travel'
    if OBJECT_RE.search(n):
        return 'objects'
    return 'symbols'

result = []
for key in cands:
    seq = list(key)
    name = ' '.join(nm(c) for c in seq if c not in (ZWJ, VS16, KEYCAP))
    if KEYCAP in seq:
        name = 'KEYCAP ' + chr(seq[0])
    if not name.strip():
        continue
    result.append({'cps': seq, 'name': name, 'group': group(seq, name)})

json.dump(result, open(OUT, 'w', encoding='utf-8'), ensure_ascii=False)
from collections import Counter
print(len(result), Counter(r['group'] for r in result))
